@Component("publisher-handler")
@ProcessingGroup("publisher-processing-group")
public class PublisherEventHandler {
	
	// core constructor
	PublisherEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePublisherEvent
     */
    @EventHandler
    public void handle( CreatePublisherEvent event) {
        entityManager.persist(new Publisher(event.getPublisherId(), event.getName(), event.getWebsite(), event.getInventorySources(), event.getDeals(), event.getCreativeApprovals(), event.getInsertionOrders(), event.getRateCards(), event.getPublisherType()));
    }

    /*
     * @param	event UpdatePublisherEvent
     */
    @EventHandler
    public Publisher handle( UpdatePublisherEvent event) {
    	entityManager.merge(new Publisher(event.getPublisherId(), event.getName(), event.getWebsite(), event.getInventorySources(), event.getDeals(), event.getCreativeApprovals(), event.getInsertionOrders(), event.getRateCards(), event.getPublisherType()));
    }
    
    /*
     * @param	event DeletePublisherEvent
     */
    @EventHandler
    public void on( DeletePublisherEvent event) {
    	Publisher entity = new Publisher();
   
    	// ------------------------------------------
    	// apply the PublisherId
    	// ------------------------------------------
    	entity.setPublisherId( event.getPublisherId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PublisherRepository publisherEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PublisherEventHandler.class.getName());

}
